struct StringFixture { char text[128];unsigned int refs; };
static StringFixture* sf(CCharStringData* p){return reinterpret_cast<StringFixture*>(p);}
static const char* text(const CCharString& s){return s.PStringData?sf(s.PStringData)->text:"";}
CCharString::CCharString():PStringData(0){}
